                            .OrderByDescending(d => d.CreatedAt)
                            .Take(100)
                            .ToListAsync();
                    }
                },
                "Refresh"
            );

            // SearchDocuments
            app.AddAsyncEndpointWithBearerAuth<DocumentSearchRequest>(
                "SearchDocuments",
                async (DataIn, LoginInfo) =>
                {
                    var req = (DocumentSearchRequest)DataIn;
                    var (from, to) = CalculateTimeRange(req.From, req.To);

                    using (var ctx = new NewinvContext())
                    {
                        // Join RefDocs with RefDocsTranscriptions manually
                        // Use distinct variable names 'd' and 't' to avoid ambiguity
                        var query = ctx.RefDocs
                            .Join(ctx.RefDocsTranscriptions,
                                  d => d.RefId,
                                  t => t.RefDoc,
                                  (d, t) => new { d, t })
                            .Where(x => x.d.CreatedAt >= from && x.d.CreatedAt <= to);

                        if (!string.IsNullOrWhiteSpace(req.Query))
                        {
                            var lowerQuery = req.Query.ToLower();
                            // Access properties on x.t (RefDocsTranscription)
                            query = query.Where(x => 
                                (x.t.TranscribedContent != null && x.t.TranscribedContent.ToLower().Contains(lowerQuery)) ||
                                (x.t.TranscriptionStructured != null && x.t.TranscriptionStructured.ToLower().Contains(lowerQuery))
                            );
                        }

                        return await query
                            .Select(x => x.d)
                            .Distinct()
                            .OrderByDescending(d => d.CreatedAt)
                            .ToListAsync();
                    }
                },
                "Refresh"
            );

            // SuggestDocuments
            app.AddAsyncEndpointWithBearerAuth<DocumentSearchRequest>(
                "SuggestDocuments",
                async (DataIn, LoginInfo) =>
                {
                    var req = (DocumentSearchRequest)DataIn;
                    var (from, to) = CalculateTimeRange(req.From, req.To);

                    using (var ctx = new NewinvContext())
                    {
                        // Join RefDocs with RefDocsTranscriptions manually
                        // Use distinct variable names 'd' and 't'
                        var query = ctx.RefDocs
                            .Join(ctx.RefDocsTranscriptions,
                                  d => d.RefId,
                                  t => t.RefDoc,
                                  (d, t) => new { d, t })
                            .Where(x => x.d.CreatedAt >= from && x.d.CreatedAt <= to);

                        if (!string.IsNullOrWhiteSpace(req.Query))
                        {
                            var terms = req.Query.Split(' ', StringSplitOptions.RemoveEmptyEntries);
                            // Access properties on x.t
                            query = query.Where(x => x.t != null && terms.Any(term => 
                                (x.t.TranscribedContent != null && x.t.TranscribedContent.ToLower().Contains(term.ToLower())) ||
                                (x.t.TranscriptionStructured != null && x.t.TranscriptionStructured.ToLower().Contains(term.ToLower()))
                            ));
                        }

                        return await query
                            .Select(x => x.d)
                            .Distinct()
                            .OrderByDescending(d => d.CreatedAt)
                            .Take(10)
                            .ToListAsync();
                    }
                },
                "Refresh"
            );

            // GetTranscriptions
            app.AddAsyncEndpointWithBearerAuth<TranscriptionIdRequest>(
                "GetTranscriptions",
                async (DataIn, LoginInfo) =>
                {
                    var req = (TranscriptionIdRequest)DataIn;
                    using (var ctx = new NewinvContext())
                    {
                        return await ctx.RefDocsTranscriptions
                            .Where(t => t.RefDoc == req.RefId)
                            .OrderByDescending(t => t.TranscribedAt)
                            .ToListAsync();
                    }
                },
                "Refresh"
            );

            // GetUntranscribed (Target of complaint)
            app.AddAsyncEndpointWithBearerAuth<object>(
                "GetUntranscribed",
                async (DataIn, LoginInfo) =>
                {
                    using (var ctx = new NewinvContext())
                    {
                        // Join RefDocs with RefDocsTranscriptions manually
                        // Use distinct variable names 'd' and 't' to avoid ambiguity
                        var query = ctx.RefDocs
                            .GroupJoin(ctx.RefDocsTranscriptions,
                                      d => d.RefId,
                                      t => t.RefDoc,
                                      (d, t) => new { d, t })
                        .Where(x => x.t == null || string.IsNullOrEmpty(x.t.TranscribedContent))
                        .Select(x => x.d) // Select the document object
                        .OrderByDescending(d => d.CreatedAt)
                        .Take(100)
                        .ToListAsync();
                    }
                },
                "Refresh"
            );

            return app;
        }

        // DTO for Search Requests
        public class DocumentSearchRequest
        {
            public string Query { get; set; }
            public DateTime? From { get; set; }
            public DateTime? To { get; set; }
        }

        public class TranscriptionIdRequest
        {
            public long RefId { get; set; }
        }

        // Helper for Time Range Calculation
        private static class RefDocsEndpoints
        {
            private static (DateTime From, DateTime To) CalculateTimeRange(DateTime? from, DateTime? to)
            {
                DateTime now = DateTime.UtcNow;
                DateTime rangeFrom, rangeTo;

                if (from.HasValue && to.HasValue)
                {
                    // Both specified
                    rangeFrom = from.Value.Kind == DateTimeKind.Utc ? from.Value : from.Value.ToUniversalTime();
                    rangeTo = to.Value.Kind == DateTimeKind.Utc ? to.Value : to.Value.ToUniversalTime();
                }
                else if (to.HasValue)
                {
                    // Only To specified: From = To - 6 months
                    rangeTo = to.Value.Kind == DateTimeKind.Utc ? to.Value : to.Value.ToUniversalTime();
                    rangeFrom = rangeTo.AddMonths(-6);
                }
                else if (from.HasValue)
                {
                    // Only From specified: To = From + 6 months
                    rangeFrom = from.Value.Kind == DateTimeKind.Utc ? from.Value : from.Value.ToUniversalTime();
                    rangeTo = rangeFrom.AddMonths(6);
                }
                else
                {
                    // None specified: From = Now - 6 months, To = Now
                    rangeTo = now;
                    rangeFrom = now.AddMonths(-6);
                }

                return (rangeFrom, rangeTo);
            }
        }
    }
}
