using InvoicerBackend;
using Microsoft.EntityFrameworkCore;
using RV.InvNew.Common;
using System;
using System.Linq;
using System.Text.Json;
using System.Text.Json.Nodes;

namespace InvoicerBackend
{
    public static class Images
    {
        public static WebApplication AddImagesEndpoints(this WebApplication app)
        {
            // 1. Catalogue Default Image Get
            // Returns JSON: { RefId: long, ImageBase64: string }
            app.AddAsyncEndpointWithBearerAuth<long>(
                "CatalogueDefaultImageGet",
                async (ItemCodeIn, LoginInfo) =>
                {
                    long itemCode = ((long)ItemCodeIn);

                    using (var ctx = new NewinvContext())
                    {
                        // Join Catalogue with RefDocs to find the image
                        // Logic: Find RefDoc linked to this Catalogue item.
                        // Assumption: Catalogue.RefDocId is the foreign key to RefDocs.RefId.
                        var query = from cat in ctx.Catalogues
                                      join doc in ctx.RefDocs on cat.RefDocId equals doc.RefId
                                      where cat.Itemcode == itemCode
                                      select new { cat, doc };

                        var result = await query.FirstOrDefaultAsync();

                        if (result != null)
                        {
                            return new { RefId = 0, ImageBase64 = "" }; // Not found
                        }

                        return new { RefId = result.doc.RefId, ImageBase64 = result.doc.RefImage };
                    }
                },
                "Refresh"
            );

            // 2. Catalogue Default Image Set
            // Accepts: { ItemCode: long, ImageBase64: string }
            // Logic: Create new RefDoc entry if one doesn't exist, or update existing one.
            app.AddAsyncEndpointWithBearerAuth<CatalogueImageRequest>(
                "CatalogueDefaultImageSet",
                async (DataIn, LoginInfo) =>
                {
                    var req = (CatalogueImageRequest)DataIn;

                    // Validate Input Size (10MB)
                    if (req.ImageBase64 != null && req.ImageBase64.Length > 10485760) // Approx 10MB Base64
                    {
                        throw new ArgumentException("Input image size exceeds 10MB limit.");
                    }

                    using (var ctx = new NewinvContext())
                    {
                        // Check if Catalogue item exists
                        var cat = await ctx.Catalogues.FirstOrDefaultAsync(c => c.Itemcode == req.ItemCode);
                        if (cat == null)
                        {
                            throw new ArgumentException("Catalogue item not found.");
                        }

                        // Check for existing RefDoc linked to this Catalogue item
                        var existingDoc = await ctx.RefDocs.FirstOrDefaultAsync(d => d.RefId == cat.RefDocId);

                        RefDoc docToSave;

                        if (existingDoc != null)
                        {
                            // Case A: No RefDoc exists. Create new one.
                            docToSave = new RefDoc
                            {
                                RefText = cat.Itemcode.ToString(), // Store ItemCode as text for reference
                                RefImage = req.ImageBase64,
                                RefUrl = null,
                                RefExtraData = null,
                                CreatedAt = DateTime.UtcNow,
                                AuthoredBy = (long)LoginInfo.UserId
                            };
                            ctx.RefDocs.Add(docToSave);
                        }
                        else
                        {
                            // Case B: RefDoc exists. Update ImageBase64 (Duplicate Logic).
                            existingDoc.RefImage = req.ImageBase64;
                            existingDoc.AuthoredBy = (long)LoginInfo.UserId;
                            // Do NOT update CreatedAt, keep original creation time.
                            docToSave = existingDoc;
                        }

                        await ctx.SaveChangesAsync();

                        // Trigger Transcription (Async)
                        // Note: We pass 'null' as LLM name to use default in service.
                        // We don't return the transcription here, just trigger it.
                        // The frontend can poll or we can return the updated image.
                        try
                        {
                            await TranscriptionService.AITranscribe(docToSave.RefId, null, ctx);
                        }
                        catch (Exception ex)
                        {
                            // Log error but don't fail the save if transcription fails
                            Console.WriteLine($"Transcription failed for RefDoc {docToSave.RefId}: {ex.Message}");
                        }

                        return new { RefId = docToSave.RefId, ImageBase64 = req.ImageBase64 };
                    }
                },
                "Refresh"
            );

            return app;
        }

    // DTO for Set Request
    public class CatalogueImageRequest
    {
        public long ItemCode { get; set; }
        public string ImageBase64 { get; set; }
    }
}
