<body>
    <div class="container">
        <h1>Edit Catalogue Item</h1>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <p style="color: red;">@ErrorMessage</p>
        }

        <div class="form-group">
            <label>Item Code</label>
            <input type="number" id="itemCode" readonly>
        </div>

        <div class="form-group">
            <label>Description</label>
            <input type="text" id="description" placeholder="Item description">
        </div>

        <div class="form-group">
            <label>Active Status</label>
            <select id="active">
                <option value="true">Active</option>
                <option value="false">Inactive</option>
            </select>
        </div>

        <button id="btnSave">Save Changes</button>
        <div id="result"></div>

        <div style="margin-top: 20px;">
            <a href="/Pages/Catalogue/Index">Back to List</a> | 
            <a href="/Pages/Catalogue/Search">Search</a>
        </div>

    <script>
        // Store current item data
        let currentItem = null;
        let currentRefDocId = null;

        function getCookie(name) {
            const value = `; ${document.cookie}`;
            const parts = value.split(`; ${name}=`);
            if (parts.length === 2) return parts.pop().split(';').shift();
        }

        async function loadItem() {
            const token = getCookie("auth-token");
            const itemCode = new URLSearchParams(window.location.search).get('itemcode');
            const resultDiv = document.getElementById('result');

            if (!token) {
                window.location.href = '/Pages/LoginWeb';
                return;
            }

            if (!itemCode) {
                resultDiv.innerText = "No item code provided.";
                return;
            }

            resultDiv.innerText = "Loading...";

            try {
                // 1. Get Catalogue Item
                const catRes = await fetch('/CatalogueDefaultImageGet', {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ ItemCode: itemCode })
                });

                if (!catRes.ok) throw new Error(`Error ${catRes.status}`);
                const cat = await catRes.json();

                if (!cat) {
                    resultDiv.innerText = "Item not found.";
                    return;
                }

                currentItem = cat;
                currentRefDocId = cat.refDocId;
                document.getElementById('itemCode').value = cat.itemcode;
                document.getElementById('description').value = cat.description || "";
                document.getElementById('active').value = cat.active ? "true" : "false";

                // 2. Get RefDoc Image (if exists)
                if (currentRefDocId && currentRefDocId > 0)
                {
                    const refDocRes = await fetch('/CatalogueDefaultImageGet', {
                        method: 'POST',
                        headers: {
                            'Authorization': `Bearer ${token}`,
                            'Content-Type': 'application/json'
                        },
                        body: JSON.stringify({ ItemCode: itemCode })
                    });

                    if (refDocRes.ok) {
                        const refDoc = await refDocRes.json();
                        if (refDoc && refDoc.refId > 0) {
                            document.getElementById('preview').src = `data:image/jpeg;base64,${refDoc.imageBase64}`;
                            document.getElementById('preview').style.display = 'block';
                        }
                    }
                }

            } catch (err) {
                resultDiv.innerText = "Error: " + err.message;
                console.error(err);
            }
        }

        document.getElementById('btnSave').addEventListener('click', async function() {
            const token = getCookie("auth-token");
            const itemCode = document.getElementById('itemCode').value;
            const description = document.getElementById('description').value;
            const active = document.getElementById('active').value === "true";
            const resultDiv = document.getElementById('result');

            if (!token) {
                window.location.href = '/Pages/LoginWeb';
                return;
            }

            if (!itemCode) {
                alert("Item Code is required.");
                return;
            }

            resultDiv.innerText = "Saving...";

            try {
                // Construct Payload using Dictionary to prevent overwriting defaults
                const payload = {
                    ItemCode: parseInt(itemCode),
                    Description: description,
                    Active: active
                    // Only send RefId if we are updating an existing image (logic handled in backend)
                    RefId: currentRefDocId > 0 ? currentRefDocId : 0 
                };

                const response = await fetch('/CatalogueDefaultImageSet', {
                    method: 'POST', // Using POST endpoint
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(payload)
                });

                if (!response.ok) {
                    const err = await response.text();
                    throw new Error(`Save failed: ${response.status} ${err}`);
                }

                const result = await response.json();
                resultDiv.innerText = JSON.stringify(result, null, 2);
                alert("Item updated successfully!");

                // Reload to get updated RefDocId
                await loadItem();

            } catch (err) {
                resultDiv.innerText = "Error: " + err.message;
                console.error(err);
            }
        });

        loadItem();
    </script>
</body>
</html>
