        </div>

        <div class="form-group">
            <label>Description</label>
            <input type="text" id="description" placeholder="Item description">
        </div>

        <div class="form-group">
            <label>Active Status</label>
            <select id="active">
                <option value="true">Active</option>
                <option value="false">Inactive</option>
            </select>
        </div>

        <div class="form-group">
            <label>Image (JPEG/PNG, Max 10MB)</label>
            <!-- accept="image/*" allows camera -->
            <input type="file" id="fileInput" accept="image/*" capture="environment">
            <img id="preview" alt="Preview" />
        </div>

        <button id="btnUpload">Upload & Transcribe</button>
        <div id="result"></div>

        <div style="margin-top: 20px;">
            <a href="/Pages/Catalogue/Index">Back to List</a> | 
            <a href="/Pages/Catalogue/Search">Search</a>
        </div>

    <script>
        function getCookie(name) {
            const value = `; ${document.cookie}`;
            const parts = value.split(`; ${name}=`);
            if (parts.length === 2) return parts.pop().split(';').shift();
        }

        // Helper to convert File (HEIC/PNG/etc) to JPEG using Canvas
        function convertToJpeg(file, maxWidth = 1920, quality = 0.9) {
            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = (e) => {
                    const img = new Image();
                    img.onload = () => {
                        const canvas = document.createElement('canvas');
                        let width = img.width;
                        let height = img.height;

                        // Resize logic
                        if (width > maxWidth) {
                            height = Math.round(height * (maxWidth / width));
                            width = maxWidth;
                        }

                        canvas.width = width;
                        canvas.height = height;

                        const ctx = canvas.getContext('2d');
                        ctx.fillStyle = "#FFFFFF";
                        ctx.fillRect(0, 0, width, height);
                        ctx.drawImage(img, 0, 0, width, height);

                        // Export to JPEG
                        const jpegDataUrl = canvas.toDataURL('image/jpeg', quality);
                        resolve(jpegDataUrl);
                    };
                    img.onerror = reject;
                    img.src = e.target.result;
                };
                reader.onerror = reject;
                reader.readAsDataURL(file);
            });
        }

        document.getElementById('fileInput').addEventListener('change', function(e) {
            const file = e.target.files[0];
            const preview = document.getElementById('preview');
            const result = document.getElementById('result');

            result.style.display = 'none';
            result.innerText = '';

            if (!file) {
                preview.style.display = 'none';
                return;
            }

            // Check Size (10MB)
            if (file.size > 10 * 1024 * 1024) {
                alert("File is too large. Max size is 10MB.");
                this.value = ''; 
                preview.style.display = 'none';
                return;
            }

            // Show Preview
            const reader = new FileReader();
            reader.onload = function(e) {
                preview.src = e.target.result;
                preview.style.display = 'block';
            };
            reader.readAsDataURL(file);
        });

        document.getElementById('btnUpload').addEventListener('click', async function() {
            const fileInput = document.getElementById('fileInput');
            const file = fileInput.files[0];
            const itemCode = document.getElementById('itemCode').value;
            const description = document.getElementById('description').value;
            const active = document.getElementById('active').value === "true";
            const resultDiv = document.getElementById('result');
            const token = getCookie("auth-token");

            if (!token) {
                window.location.href = '/Pages/LoginWeb';
                return;
            }

            if (!file) {
                alert("Please select a file first.");
                return;
            }

            if (!itemCode) {
                alert("Item Code is required.");
                return;
            }

            resultDiv.style.display = 'block';
            resultDiv.innerText = "Processing image (converting to JPEG)...";

            try {
                // 1. Convert to JPEG using Canvas
                const jpegDataUrl = await convertToJpeg(file);

                // Strip prefix to get Base64 string
                const base64Image = jpegDataUrl.split(',')[1];

                resultDiv.innerText = "Uploading...";

                // 2. Save Catalogue Item (Create) and Set Image
                const payload = {
                    ItemCode: parseInt(itemCode),
                    Description: description,
                    Active: active,
                    ImageBase64: base64Image
                };

                const response = await fetch('/CatalogueDefaultImageSet', {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(payload)
                });

                if (!response.ok) {
                    const err = await response.text();
                    throw new Error(`Save failed: ${response.status} ${err}`);
                }

                const result = await response.json();
                resultDiv.innerText = JSON.stringify(result, null, 2);
                alert("Item created successfully!");

                fileInput.value = '';
                document.getElementById('preview').style.display = 'none';

            } catch (err) {
                resultDiv.innerText = "Error: " + err.message;
                console.error(err);
            }
        });
    </script>
</body>
</html>
