                        if (req.Posted.HasValue)
                        {
                            query = query.Where(a => a.Posted == req.Posted.Value);
                        }

                        return await query
                            .OrderByDescending(a => a.CreatedAt)
                            .Take(100)
                            .ToListAsync();
                    }
                },
                "Refresh"
