                "SetSuggestedPrices",
                async (DataIn, LoginInfo) =>
                {
                    var req = (SetSuggestedPricesRequest)DataIn;

                    using (var ctx = new NewinvContext())
                    {
                        // 1. Remove existing
                        var existing = await ctx.SuggestedPrices
                            .Where(p => p.Itemcode == req.ItemCode)
                            .ToListAsync();

                        ctx.SuggestedPrices.RemoveRange(existing);

                        // 2. Add new
                        if (req.Prices != null)
                        {
                            foreach (var price in req.Prices.Distinct())
                            {
                                ctx.SuggestedPrices.Add(new SuggestedPrice
                                {
                                    Itemcode = req.ItemCode,
                                    Price = price,
                                    AddedAt = DateTime.UtcNow,
                                    AddedBy = (long)LoginInfo.UserId
                                });
                            }
                        }

                        await ctx.SaveChangesAsync();
                        return true;
                    }
                },
                "Refresh"
            );
