            public class AutoSelectBatchRequest
            {
                public long ItemCode { get; set; }
                public double Quantity { get; set; }
            }

            app.AddAsyncEndpointWithBearerAuth<AutoSelectBatchRequest>(
                "AutoSelectBatchesWeb",
                async (DataIn, LoginInfo) =>
                {
                    var req = (AutoSelectBatchRequest)DataIn;
                    using (var ctx = new NewinvContext())
                    {
                        // FIFO: Order by ExpDate, then MfgDate
                        var availableBatches = await ctx.Inventories
                            .Where(i => i.Itemcode == req.ItemCode && i.Units > 0)
                            .OrderBy(i => i.ExpDate ?? DateTime.MaxValue)
                            .ThenBy(i => i.MfgDate ?? DateTime.MaxValue)
                            .ToListAsync();

                        var selection = new List<object>();
                        double remaining = req.Quantity;

                        foreach (var batch in availableBatches)
                        {
                            if (remaining <= 0) break;

                            double take = Math.Min(batch.Units, remaining);
                            selection.Add(new { BatchCode = batch.Batchcode, Quantity = take, batch.Units, batch.ExpDate });
                            remaining -= take;
                        }

                        if (remaining > 0)
                        {
                            throw new ArgumentException($"Insufficient stock. Short by {remaining}.");
                        }

                        return selection;
                    }
                },
                "Refresh"
            );
